import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodo";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function postTodoListUserTodos(props: {
  user: UserPayload;
  body: ITodoListTodo.ICreate;
}): Promise<ITodoListTodo> {
  // Step 1: Enforce per-user unique, active (incomplete) title constraint
  const existing = await MyGlobal.prisma.todo_list_todos.findFirst({
    where: {
      todo_list_user_id: props.user.id,
      title: props.body.title,
      completed: false,
    },
  });
  if (existing) {
    throw new HttpException(
      "A pending Todo with this title already exists.",
      409,
    );
  }

  // Step 2: Generate UUID and timestamps
  const now = toISOStringSafe(new Date());
  const todoId = v4();

  // Step 3: Create Todo
  const created = await MyGlobal.prisma.todo_list_todos.create({
    data: {
      id: todoId,
      title: props.body.title,
      description: props.body.description ?? null,
      completed: false,
      created_at: now,
      updated_at: now,
      completed_at: null,
      todo_list_user_id: props.user.id,
    },
  });

  return {
    id: created.id,
    title: created.title,
    description: created.description ?? null,
    completed: created.completed,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    completed_at:
      created.completed_at === null
        ? null
        : toISOStringSafe(created.completed_at),
    todo_list_user_id: created.todo_list_user_id,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { UserPayload } from "../decorators/payload/UserPayload";

export async function deleteTodoListUserTodosTodoId(props: {
  user: UserPayload;
  todoId: string;
}): Promise<void> {
  const todo = await MyGlobal.prisma.todo_list_todos.findUnique({
    where: {
      id: props.todoId,
    },
  });

  if (!todo) {
    throw new HttpException("Todo not found", 404);
  }

  if (todo.todo_list_user_id !== props.user.id) {
    throw new HttpException(
      "You do not have permission to delete this todo",
      403,
    );
  }

  await MyGlobal.prisma.todo_list_todos.delete({
    where: {
      id: props.todoId,
    },
  });
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";
import { IPageITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoListUser";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function patchTodoListUserUsers(props: {
  user: UserPayload;
  body: ITodoListUser.IRequest;
}): Promise<IPageITodoListUser.ISummary> {
  const page = props.body.page;
  const limit = props.body.limit;
  const skip = (page - 1) * limit;
  const { q } = props.body;

  const where = q
    ? {
        OR: [
          { email: { contains: q, mode: Prisma.QueryMode.insensitive } },
          { display_name: { contains: q, mode: Prisma.QueryMode.insensitive } },
        ],
      }
    : undefined;

  const [users, total] = await Promise.all([
    MyGlobal.prisma.todo_list_users.findMany({
      where,
      skip,
      take: limit,
      orderBy: { created_at: "desc" },
    }),
    MyGlobal.prisma.todo_list_users.count({ where }),
  ]);

  return {
    pagination: {
